/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01.c
 *
 * GC9D01 160x160 round LCD bring-up (4-wire MCU SPI), two panels.
 *
 * Init command table copied verbatim -- all 50 entries -- from
 * bk_avdk_smp release/v3.1.1
 * ap/components/bk_peripheral/src/lcd/spi/lcd_spi_gc9d01.c
 * (gc9d01_init_cmds).  The bring-up sequence follows bk_lcd_spi_init() in
 * ap/middleware/driver/lcd/lcd_spi_driver.c.
 *
 * ---------------------------------------------------------------------
 * Dual panel
 * ---------------------------------------------------------------------
 * The board carries two GC9D01 footprints (sheet 5/6: LCD1 labelled 单屏,
 * LCD2 labelled 双屏) and both can be populated -- the two "eyes" of the
 * product.  Each has its own QSPI controller, D/C and RESET; they share the
 * 3.3V rail and the backlight.  Pin evidence and the independent
 * corroboration from bk_solution_ai are in bk7258_qspi.c's header.
 *
 *   display 0 -> bus 1 (QSPI1), D/C GPIO5, RESET GPIO45   [LCD1 footprint]
 *   display 1 -> bus 0 (QSPI0), D/C GPIO7, RESET GPIO6    [LCD2 footprint]
 *
 * display 0 is deliberately the QSPI1 panel: that is the one that was
 * brought up and verified first, so /dev/fb0 keeps pointing at the same
 * physical screen it always did.
 *
 * A missing second panel is not an error.  The panel has no readable ID
 * register, so an unpopulated footprint is indistinguishable from a working
 * one from the software side -- every command still "completes".  Failing
 * bring-up because display 1 is absent would therefore be wrong, and
 * bk7258_gc9d01_panel_init() cannot detect it either way.
 *
 * ---------------------------------------------------------------------
 * 2026-08-10: why the panel was dark even though the bus was busy
 * ---------------------------------------------------------------------
 * Four independent causes, each on its own sufficient to produce a black
 * screen:
 *
 *  1. Panel power was off.  The LCD connector's VDD and LEDA both come from
 *     LDO_3V3, whose enable is the LDO33_EN net = GPIO52.  Nothing asserted
 *     it -- worse, bk7258_pwm.c owned GPIO52 as "BK7258_MOTOR_LDO_GPIO" and
 *     drove it *low* in its setup path, which runs earlier in
 *     bk7258_bringup() than the display does.  GPIO52 is now a
 *     reference-counted shared rail (bk7258_ldo33.c).
 *
 *  2. Backlight was off.  LEDK comes from the LCD_BL net, switched by Q3
 *     (MMBT3904) from LCD_BL_PWM = GPIO25.  A GC9D01 module is a
 *     transmissive TFT: with the backlight off the GRAM contents are
 *     invisible no matter how correct they are.
 *
 *  3. No D/C line -- the pad was pinmuxed as a controller IO instead.
 *  4. Wrong wire protocol (QSPI-panel header instead of bare opcodes).
 *
 * Items 3 and 4 are documented in bk7258_qspi.c.  Two further gaps fixed
 * here: the previous table dropped 20 of the 50 entries, and CASET/RASET
 * was never programmed -- bk_lcd_spi_init() ends by setting the drawing
 * window to the full panel, and a GC9-series panel's window registers have
 * no guaranteed reset value.
 *
 * Success criterion note: GC9D01 exposes no readable ID register (there is
 * no RDID opcode anywhere in the vendor's table), so "the sequence was sent
 * without timing out" has never been evidence that the panel accepted it.
 * The only proof is pixels on the glass.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include "bk7258_gpio.h"
#include "bk7258_ldo33.h"
#include "bk7258_qspi.h"
#include "bk7258_gc9d01_fb.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Shared across both panels.
 *
 *   P25 -> LCD_BL_PWM -> Q3 base -> LCD_BL -> both panels' LEDK
 *   P52 -> LDO33_EN   -> LDO_3V3 -> both panels' VDD + LEDA
 */

#define GC9D01_BACKLIGHT_PIN 25u

/* Time for LDO_3V3 to come up before any panel is touched.  No datasheet
 * citation; 20ms is generously above any small LDO's soft-start and costs
 * nothing once per boot.
 */

#define GC9D01_LDO_SETTLE_MS 20u

/* Delay-marker convention from the vendor table: data_len == 0xFF means
 * "this is not a command, delay data[0] milliseconds", handled by
 * bk_lcd_spi_init() rather than by the bus driver.
 */

#define GC9D01_DELAY_MARKER  0xFFu

struct gc9d01_init_cmd
{
  uint8_t cmd;
  uint8_t data[32];
  uint8_t data_len;
};

/* Per-panel wiring.  Indexed by display number. */

struct gc9d01_panel_s
{
  int bus;                 /* BK7258_LCD_BUS0 / BUS1 */
  unsigned int dc_pin;
  unsigned int reset_pin;
  const char *footprint;   /* schematic designator, for logs */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct gc9d01_panel_s g_panels[GC9D01_NDISPLAYS] =
{
  {
    .bus       = BK7258_LCD_BUS1,
    .dc_pin    = 5u,
    .reset_pin = 45u,
    .footprint = "LCD1",
  },
  {
    .bus       = BK7258_LCD_BUS0,
    .dc_pin    = 7u,
    .reset_pin = 6u,
    .footprint = "LCD2",
  },
};

static bool g_rail_held;

/* Which panels have already been through the reset and command sequence.
 * fb_register() -> up_fbinitialize() asks for its own display again after
 * bring-up has initialised both together, and re-sending the sequence would
 * reset the glass mid-greeting.
 */

static bool g_panel_ready[GC9D01_NDISPLAYS];

/* All 50 entries of gc9d01_init_cmds, in order, including the delay marker
 * and the trailing Display On.  Earlier revisions of this file omitted 20
 * of them -- 11 because the old bus driver could not carry more than 4
 * payload bytes, and 9 with no stated reason -- which meant the panel's
 * gamma, porch and power-control registers were left at reset values.
 */

static const struct gc9d01_init_cmd g_gc9d01_init_cmds[] =
{
  { 0xFE, { 0x00 }, 0 },
  { 0xEF, { 0x00 }, 0 },
  { 0x80, { 0xFF }, 1 },
  { 0x81, { 0xFF }, 1 },
  { 0x82, { 0xFF }, 1 },
  { 0x83, { 0xFF }, 1 },
  { 0x84, { 0xFF }, 1 },
  { 0x85, { 0xFF }, 1 },
  { 0x86, { 0xFF }, 1 },
  { 0x87, { 0xFF }, 1 },
  { 0x88, { 0xFF }, 1 },
  { 0x89, { 0xFF }, 1 },
  { 0x8A, { 0xFF }, 1 },
  { 0x8B, { 0xFF }, 1 },
  { 0x8C, { 0xFF }, 1 },
  { 0x8D, { 0xFF }, 1 },
  { 0x8E, { 0xFF }, 1 },
  { 0x8F, { 0xFF }, 1 },
  { 0x3A, { 0x05 }, 1 },
  { 0xEC, { 0x01 }, 1 },
  { 0x74, { 0x02, 0x0E, 0x00, 0x00, 0x00, 0x00, 0x00 }, 7 },
  { 0x98, { 0x3E, 0x99, 0x3E }, 3 },
  { 0xB5, { 0x0D, 0x0D }, 2 },
  { 0x60, { 0x38, 0x0F, 0x79, 0x67 }, 4 },
  { 0x61, { 0x38, 0x11, 0x79, 0x67 }, 4 },
  { 0x64, { 0x38, 0x17, 0x71, 0x5F, 0x79, 0x67 }, 6 },
  { 0x65, { 0x38, 0x13, 0x71, 0x5B, 0x79, 0x67 }, 6 },
  { 0x6A, { 0x00, 0x00 }, 2 },
  { 0x6C, { 0x22, 0x02, 0x22, 0x02, 0x22, 0x22, 0x50 }, 7 },
  { 0x6E,
      { 0x03, 0x03, 0x01, 0x01, 0x00, 0x00, 0x0F, 0x0F,
        0x0D, 0x0D, 0x0B, 0x0B, 0x09, 0x09, 0x00, 0x00,
        0x00, 0x00, 0x0A, 0x0A, 0x0C, 0x0C, 0x0E, 0x0E,
        0x10, 0x10, 0x00, 0x00, 0x02, 0x02, 0x04, 0x04 }, 32 },
  { 0xBF, { 0x01 }, 1 },
  { 0xF9, { 0x40 }, 1 },
  { 0x9B, { 0x3B }, 1 },
  { 0x93, { 0x33, 0x7F, 0x00 }, 3 },
  { 0x7E, { 0x30 }, 1 },
  { 0x70, { 0x0D, 0x02, 0x08, 0x0D, 0x02, 0x08 }, 6 },
  { 0x71, { 0x0D, 0x02, 0x08 }, 3 },
  { 0x91, { 0x0E, 0x09 }, 2 },
  { 0xC3, { 0x18 }, 1 },
  { 0xC4, { 0x18 }, 1 },
  { 0xC9, { 0x3C }, 1 },
  { 0xF0, { 0x13, 0x15, 0x04, 0x05, 0x01, 0x38 }, 6 },
  { 0xF2, { 0x13, 0x15, 0x04, 0x05, 0x01, 0x34 }, 6 },
  { 0xF1, { 0x4B, 0xB8, 0x7B, 0x34, 0x35, 0xEF }, 6 },
  { 0xF3, { 0x47, 0xB4, 0x72, 0x34, 0x35, 0xDA }, 6 },
  { 0x36, { 0x00 }, 1 },
  { 0x34, { 0x00 }, 0 },                    /* Tearing Effect line off */
  { 0x11, { 0x00 }, 0 },                    /* Sleep Out */
  { 0x00, { 0x78 }, GC9D01_DELAY_MARKER },  /* delay 120ms */
  { 0x29, { 0x00 }, 0 },                    /* Display On */
};

#define GC9D01_INIT_CMD_COUNT \
  (sizeof(g_gc9d01_init_cmds) / sizeof(g_gc9d01_init_cmds[0]))

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: gc9d01_hw_reset
 *
 * Description:
 *   High-low-high pulse on RESET, mirroring lcd_spi_device_gpio_init():
 *   high, low for 100ms, high, then 120ms settle before any command.  The
 *   120ms figure is the de-facto standard across every panel driver in the
 *   same bk_avdk_smp codebase (lcd_st7701s.c:48, lcd_nt35512.c:859,
 *   lcd_st7789v.c:167 all use rtos_delay_milliseconds(120) post-reset).
 *
 *   Every panel in the mask is pulsed together, because all three waits are
 *   the panel's own settling time and not bus occupancy: two panels on
 *   separate RESET pins and separate QSPI buses have no reason to wait one
 *   after the other.  Doing them in series cost 230ms per panel and was
 *   half of the delay between reset and the first pixel on the glass.
 *
 ****************************************************************************/

static void gc9d01_hw_reset(int displays)
{
  int display;

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((displays & (1 << display)) != 0)
        {
          bk7258_gpio_output(g_panels[display].reset_pin, true);
        }
    }

  up_mdelay(10);

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((displays & (1 << display)) != 0)
        {
          bk7258_gpio_write(g_panels[display].reset_pin, false);
        }
    }

  up_mdelay(100);

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((displays & (1 << display)) != 0)
        {
          bk7258_gpio_write(g_panels[display].reset_pin, true);
        }
    }

  up_mdelay(120);
}

/****************************************************************************
 * Name: gc9d01_set_window
 *
 * Description:
 *   CASET/RASET, 16-bit big-endian start and end.  bk_lcd_spi_init() ends
 *   with this for the full panel area; nothing in the command table sets
 *   it, so without this call the drawing window is whatever the panel's
 *   reset state happens to be.
 *
 ****************************************************************************/

static bool gc9d01_set_window(int bus, uint16_t x0, uint16_t y0,
                              uint16_t x1, uint16_t y1)
{
  uint8_t args[4];

  args[0] = (uint8_t)(x0 >> 8);
  args[1] = (uint8_t)(x0 & 0xff);
  args[2] = (uint8_t)(x1 >> 8);
  args[3] = (uint8_t)(x1 & 0xff);

  if (!bk7258_lcd_spi_write_cmd_data(bus, GC9D01_CMD_CASET, args, 4))
    {
      return false;
    }

  args[0] = (uint8_t)(y0 >> 8);
  args[1] = (uint8_t)(y0 & 0xff);
  args[2] = (uint8_t)(y1 >> 8);
  args[3] = (uint8_t)(y1 & 0xff);

  return bk7258_lcd_spi_write_cmd_data(bus, GC9D01_CMD_RASET, args, 4);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_gc9d01_bus(int display)
{
  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  return g_panels[display].bus;
}

bool bk7258_gc9d01_window_full(int display)
{
  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return false;
    }

  return gc9d01_set_window(g_panels[display].bus, 0, 0,
                           GC9D01_XRES - 1, GC9D01_YRES - 1);
}

void bk7258_gc9d01_backlight(bool on)
{
  bk7258_gpio_output(GC9D01_BACKLIGHT_PIN, on);
}

int bk7258_gc9d01_panels_init(int displays)
{
  int pending = 0;
  int display;
  size_t i;

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((displays & (1 << display)) != 0 && !g_panel_ready[display])
        {
          pending |= 1 << display;
        }
    }

  if (pending == 0)
    {
      /* Either nothing was asked for, or every panel asked for is already
       * up: up_fbinitialize() calls this again per display after bring-up
       * has done both, and re-running the sequence would blank the glass.
       */

      return (displays & ((1 << GC9D01_NDISPLAYS) - 1)) != 0 ? OK : -EINVAL;
    }

  /* Power first, and only once: the rail is shared, so take a reference on
   * behalf of the display subsystem as a whole rather than per panel.
   */

  if (!g_rail_held)
    {
      printf("gc9d01: LDO33 rail on (refs=%u)\n", bk7258_ldo33_request());
      g_rail_held = true;
      up_mdelay(GC9D01_LDO_SETTLE_MS);
    }

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((pending & (1 << display)) != 0)
        {
          printf("gc9d01[%d/%s]: hardware reset (RST=GPIO%u)\n", display,
                 g_panels[display].footprint,
                 (unsigned int)g_panels[display].reset_pin);
        }
    }

  gc9d01_hw_reset(pending);

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((pending & (1 << display)) != 0)
        {
          bk7258_lcd_spi_init(g_panels[display].bus,
                              g_panels[display].dc_pin);
          printf("gc9d01[%d/%s]: sending %u init entries\n", display,
                 g_panels[display].footprint,
                 (unsigned int)GC9D01_INIT_CMD_COUNT);
        }
    }

  /* One pass over the command table, feeding every panel from it.  The table
   * is walked once rather than once per panel so that its delay marker --
   * the 120ms the controller needs after Sleep Out -- is waited out once for
   * all of them instead of once each.
   */

  for (i = 0; i < GC9D01_INIT_CMD_COUNT; i++)
    {
      const struct gc9d01_init_cmd *entry = &g_gc9d01_init_cmds[i];

      if (entry->data_len == GC9D01_DELAY_MARKER)
        {
          up_mdelay(entry->data[0]);
          continue;
        }

      for (display = 0; display < GC9D01_NDISPLAYS; display++)
        {
          if ((pending & (1 << display)) == 0)
            {
              continue;
            }

          if (!bk7258_lcd_spi_write_cmd_data(g_panels[display].bus,
                                             entry->cmd, entry->data,
                                             entry->data_len))
            {
              printf("gc9d01[%d]: cmd 0x%02x (entry %u) timed out, "
                     "aborting\n", display, entry->cmd, (unsigned int)i);

              /* Drop this panel and keep going: on a two-panel board one
               * dead bus must not cost the other panel its init sequence.
               */

              pending &= ~(1 << display);
            }
        }

      if (pending == 0)
        {
          return -EIO;
        }
    }

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((pending & (1 << display)) == 0)
        {
          continue;
        }

      if (!bk7258_gc9d01_window_full(display))
        {
          printf("gc9d01[%d]: CASET/RASET failed\n", display);
          pending &= ~(1 << display);
          continue;
        }

      g_panel_ready[display] = true;

      printf("gc9d01[%d/%s]: init sequence sent, backlight on\n", display,
             g_panels[display].footprint);
    }

  if (pending == 0)
    {
      return -EIO;
    }

  /* Backlight is shared, so switching it on for one panel switches it on
   * for both.  Harmless to repeat.
   */

  bk7258_gc9d01_backlight(true);

  return OK;
}

int bk7258_gc9d01_panel_init(int display)
{
  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  return bk7258_gc9d01_panels_init(1 << display);
}

/****************************************************************************
 * Name: bk7258_gc9d01_test
 *
 * Description:
 *   Legacy standalone entry point, kept as a thin wrapper so panel 0 can be
 *   brought up without the framebuffer layer.  The caveat that has always
 *   applied to it still applies: "the sequence was sent without hanging" is
 *   not evidence that the panel accepted it.  Use
 *   bk7258_gc9d01_fb_test_pattern() for the only real check.
 *
 ****************************************************************************/

int bk7258_gc9d01_test(int argc, char **argv)
{
  UNUSED(argc);
  UNUSED(argv);

  return bk7258_gc9d01_panel_init(0);
}
/****************************************************************************
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_GC9D01_H
#define __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_GC9D01_H

int bk7258_gc9d01_test(int argc, char **argv);

#endif

/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01_fb.h
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_GC9D01_FB_H
#define __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_GC9D01_FB_H

#include <stdbool.h>
#include <stdint.h>

/* Number of panels this board can drive.  Both GC9D01 footprints (sheet
 * 5/6's LCD1 "单屏" and LCD2 "双屏") get a framebuffer, exposed as
 * /dev/fb0 and /dev/fb1.  display 0 is the QSPI1 panel, which is the one
 * that was brought up first -- keeping it at index 0 means /dev/fb0 still
 * refers to the same physical screen as before dual-panel support.
 */

#define GC9D01_NDISPLAYS 2

/* Panel geometry, from the vendor's own device table
 * (bk_avdk_smp/ap/components/bk_peripheral/src/lcd/spi/lcd_spi_gc9d01.c:
 * lcd_device_gc9d01 = { .width = 160, .height = 160 }).  One RGB565 frame
 * is 160*160*2 = 51200 bytes.
 */

#define GC9D01_XRES   160
#define GC9D01_YRES   160
#define GC9D01_BPP    16
#define GC9D01_STRIDE (GC9D01_XRES * 2)
#define GC9D01_FBLEN  (GC9D01_STRIDE * GC9D01_YRES)

/* Column/row address set, standard MIPI DCS opcodes the GC9 series
 * follows.  RAMWR (0x2C) is issued by the bus driver as part of the frame
 * push, so it is not needed here.
 */

#define GC9D01_CMD_CASET 0x2A
#define GC9D01_CMD_RASET 0x2B

/* Rail power-up (once, shared), panel reset, MCU-SPI bring-up and the
 * GC9D01 initialization command sequence for one display, ending with the
 * full-panel drawing window and the backlight on (also shared).
 * Implemented in bk7258_gc9d01.c, which owns the command table.  Returns OK
 * or a negated errno.
 *
 * Note that a missing panel cannot be detected: GC9D01 has no readable ID
 * register, so an unpopulated footprint accepts the whole sequence exactly
 * as a working one does.
 */

int bk7258_gc9d01_panel_init(int display);

/* Same, for a bitmask of panels at once.  Worth having because the sequence
 * is almost entirely waiting -- 20ms rail, 230ms reset pulse, 120ms after
 * Sleep Out -- and those waits belong to the panels, not to the bus: done
 * per panel they cost 350ms each, done together they cost 350ms in total.
 * Panels already initialised are skipped, so calling this for both panels
 * from bring-up and then letting up_fbinitialize() ask again per display is
 * safe.
 */

int bk7258_gc9d01_panels_init(int displays);

/* Which LCD bus a display is wired to; negative on a bad index. */

int bk7258_gc9d01_bus(int display);

/* Set the drawing window to the whole panel.  Exposed because the
 * framebuffer's update path re-asserts it before every frame, and the
 * pin/opcode knowledge belongs to the panel driver.
 */

bool bk7258_gc9d01_window_full(int display);

/* Backlight (LCD_BL_PWM -> Q3 -> LEDK) on/off.  Shared by both panels --
 * there is one switch for the whole board.
 */

void bk7258_gc9d01_backlight(bool on);

/* Bring-up helpers: fill one display's framebuffer with a solid colour, or
 * draw a four-quadrant test pattern, and push it.  These exist because
 * GC9D01 has no readable ID register -- until something is visible on the
 * glass there is no evidence the init sequence took effect.
 */

int bk7258_gc9d01_fb_fill(int display, uint16_t rgb565);
int bk7258_gc9d01_fb_test_pattern(int display);

/* Boot greeting: the word "hello" centred on the panel.  This is what
 * bk7258_bringup() pushes now; the quadrant pattern above stays because it is
 * the diagnostic that makes a byte-order or stride error visible, and it is
 * still reachable from the shell as 'camera_preview pattern'.
 */

int bk7258_gc9d01_fb_hello(int display);

/* The boot animation: writes the greeting one pen stroke at a time, using the
 * same renderer and stroke font as the 'hello' shell command.  displays is a
 * bitmask of panels; every step pushes a full frame to each of them, so the
 * push sets the pace (see the implementation for the measured cost).
 */

int bk7258_gc9d01_fb_hello_animate(int displays, int steps);

/* Draw one word (with a colour) or two lines, and push once.  Used by the
 * event-driven status screen; see bk7258_status_screen.c for why the product
 * path draws these instead of a live preview.  Returns OK, -EINVAL for text
 * the stroke font cannot draw, or -ENODEV if the panel is not up.
 */

int bk7258_gc9d01_fb_text(int display, FAR const char *text,
                          uint16_t colour);
int bk7258_gc9d01_fb_two_lines(int display, FAR const char *line1,
                               FAR const char *line2);

#endif /* __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_GC9D01_FB_H */
/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01_fb.c
 *
 * openvela framebuffer driver for the GC9D01 panels (160x160 round, RGB565,
 * one per QSPI controller).  Implements the three hooks fb_register() needs
 * -- up_fbinitialize(), up_fbgetvplane(), up_fbuninitialize() -- plus the
 * fb_vtable_s entries required for a panel that has no autonomous refresh:
 * getvideoinfo, getplaneinfo and updatearea.
 *
 * Why updatearea is mandatory here: a RAM-less RGB parallel panel is
 * scanned out continuously by an LCD controller, so writing the
 * framebuffer is enough.  GC9D01 has its own GRAM and is written over a
 * serial bus, so nothing reaches the glass until the driver explicitly
 * pushes it.  Without CONFIG_FB_UPDATE + this callback the screen would
 * simply never change.
 *
 * ---------------------------------------------------------------------
 * Multiple displays
 * ---------------------------------------------------------------------
 * fb_register(display, plane) (include/nuttx/video/fb.h) calls
 * up_fbinitialize(display), then up_fbgetvplane(display, plane), then
 * fb_register_device(), which names the node /dev/fb<display>.  So exposing
 * two panels is just a matter of calling fb_register() twice.
 *
 * The constraint that shapes this file: fb_vtable_s's callbacks receive
 * only the vtable pointer, with no display argument.  A single shared
 * vtable therefore cannot tell which panel it is being asked about.  Each
 * display consequently gets its own state structure whose *first* member is
 * the vtable, so a callback can recover its own state by casting the vtable
 * pointer back (the usual container-of trick, valid here because the vtable
 * sits at offset 0).
 *
 * Framebuffers come from the kernel heap: 2 x 51200 = 100KB out of roughly
 * 300KB, which is affordable and much faster for the CPU to write than
 * PSRAM (which is mapped non-cacheable).  The camera's own frame buffers do
 * live in PSRAM -- they are 614400 bytes each and have no alternative.
 *
 * The panels are round: the corners of the 160x160 square are not visible.
 * That is a composition concern for whatever draws into the framebuffer,
 * not something this driver compensates for.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/clock.h>
#include <nuttx/video/fb.h>

#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <arch/board/hello_paint.h>

#include "bk7258_qspi.h"
#include "bk7258_gc9d01_fb.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* vtable MUST stay first: the callbacks recover this structure by casting
 * their vtable argument, since fb_vtable_s carries no display index.
 */

struct gc9d01_fb_s
{
  struct fb_vtable_s vtable;
  int display;
  int bus;
  FAR uint8_t *fbmem;
  uint32_t updates;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int gc9d01_getvideoinfo(FAR struct fb_vtable_s *vtable,
                               FAR struct fb_videoinfo_s *vinfo);
static int gc9d01_getplaneinfo(FAR struct fb_vtable_s *vtable, int planeno,
                               FAR struct fb_planeinfo_s *pinfo);
#ifdef CONFIG_FB_UPDATE
static int gc9d01_updatearea(FAR struct fb_vtable_s *vtable,
                             FAR const struct fb_area_s *area);
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct gc9d01_fb_s g_gc9d01_fb[GC9D01_NDISPLAYS] =
{
  {
    .vtable =
      {
        .getvideoinfo = gc9d01_getvideoinfo,
        .getplaneinfo = gc9d01_getplaneinfo,
#ifdef CONFIG_FB_UPDATE
        .updatearea   = gc9d01_updatearea,
#endif
      },
    .display = 0,
    .bus     = -1,
  },
  {
    .vtable =
      {
        .getvideoinfo = gc9d01_getvideoinfo,
        .getplaneinfo = gc9d01_getplaneinfo,
#ifdef CONFIG_FB_UPDATE
        .updatearea   = gc9d01_updatearea,
#endif
      },
    .display = 1,
    .bus     = -1,
  },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline FAR struct gc9d01_fb_s *
gc9d01_from_vtable(FAR struct fb_vtable_s *vtable)
{
  /* Safe because .vtable is the first member of struct gc9d01_fb_s. */

  return (FAR struct gc9d01_fb_s *)vtable;
}

static int gc9d01_getvideoinfo(FAR struct fb_vtable_s *vtable,
                               FAR struct fb_videoinfo_s *vinfo)
{
  if (vtable == NULL || vinfo == NULL)
    {
      return -EINVAL;
    }

  vinfo->fmt     = FB_FMT_RGB16_565;
  vinfo->xres    = GC9D01_XRES;
  vinfo->yres    = GC9D01_YRES;
  vinfo->nplanes = 1;

  return OK;
}

static int gc9d01_getplaneinfo(FAR struct fb_vtable_s *vtable, int planeno,
                               FAR struct fb_planeinfo_s *pinfo)
{
  FAR struct gc9d01_fb_s *priv;

  if (vtable == NULL || pinfo == NULL || planeno != 0)
    {
      return -EINVAL;
    }

  priv = gc9d01_from_vtable(vtable);

  /* Single buffer: fbcount is 1, so yres_virtual == yres and fblen is one
   * frame.  If a second buffer is added later, fblen/yres_virtual must grow
   * with it.
   */

  pinfo->fbmem        = priv->fbmem;
  pinfo->fblen        = GC9D01_FBLEN;
  pinfo->stride       = GC9D01_STRIDE;
  pinfo->display      = priv->display;
  pinfo->bpp          = GC9D01_BPP;
  pinfo->xres_virtual = GC9D01_XRES;
  pinfo->yres_virtual = GC9D01_YRES;
  pinfo->xoffset      = 0;
  pinfo->yoffset      = 0;

  return OK;
}

/****************************************************************************
 * Name: gc9d01_push
 *
 * Description:
 *   Re-assert the full-panel window and stream the framebuffer out.
 *
 ****************************************************************************/

static int gc9d01_push(FAR struct gc9d01_fb_s *priv)
{
  clock_t start = clock_systime_ticks();

  if (priv->fbmem == NULL || priv->bus < 0)
    {
      return -ENODEV;
    }

  if (!bk7258_gc9d01_window_full(priv->display))
    {
      return -EIO;
    }

  if (!bk7258_lcd_spi_write_frame(priv->bus, priv->fbmem, GC9D01_FBLEN))
    {
      printf("gc9d01_fb[%d]: pixel burst failed\n", priv->display);
      return -EIO;
    }

  priv->updates++;

  /* First few pushes get a timing report: it is the only way to know the
   * real cost of a frame on this bus, which decides whether the preview
   * path needs DMA.  After that stay quiet -- this runs per displayed
   * frame.
   */

  if (priv->updates <= 3)
    {
      uint32_t ms = TICK2MSEC(clock_systime_ticks() - start);

      printf("gc9d01_fb[%d]: update %u: %d bytes in %ums "
             "(%u frames on bus)\n", priv->display,
             (unsigned int)priv->updates, GC9D01_FBLEN, (unsigned int)ms,
             (unsigned int)bk7258_lcd_spi_frame_count(priv->bus));
    }

  return OK;
}

#ifdef CONFIG_FB_UPDATE
static int gc9d01_updatearea(FAR struct fb_vtable_s *vtable,
                             FAR const struct fb_area_s *area)
{
  /* Partial updates would need a per-row copy out of the framebuffer,
   * because the panel expects a densely packed rectangle while the
   * framebuffer rows are GC9D01_STRIDE apart.  At 51200 bytes a full frame
   * is cheap enough that this always pushes everything and ignores the
   * requested rectangle.
   */

  UNUSED(area);

  if (vtable == NULL)
    {
      return -EINVAL;
    }

  return gc9d01_push(gc9d01_from_vtable(vtable));
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int up_fbinitialize(int display)
{
  FAR struct gc9d01_fb_s *priv;
  int ret;

  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  priv = &g_gc9d01_fb[display];

  if (priv->fbmem == NULL)
    {
      priv->fbmem = kmm_zalloc(GC9D01_FBLEN);
      if (priv->fbmem == NULL)
        {
          printf("gc9d01_fb[%d]: cannot allocate %d-byte framebuffer\n",
                 display, GC9D01_FBLEN);
          return -ENOMEM;
        }
    }

  /* Rail, panel reset, bus bring-up and the init command sequence.  Kept in
   * bk7258_gc9d01.c so the command table and the pin map have a single
   * owner.
   */

  ret = bk7258_gc9d01_panel_init(display);
  if (ret < 0)
    {
      printf("gc9d01_fb[%d]: panel init failed: %d\n", display, ret);
      kmm_free(priv->fbmem);
      priv->fbmem = NULL;
      return ret;
    }

  priv->bus = bk7258_gc9d01_bus(display);

  printf("gc9d01_fb[%d]: %dx%d RGB565, framebuffer %d bytes at %p, bus %d\n",
         display, GC9D01_XRES, GC9D01_YRES, GC9D01_FBLEN, priv->fbmem,
         priv->bus);

  return OK;
}

FAR struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (display < 0 || display >= GC9D01_NDISPLAYS || vplane != 0)
    {
      return NULL;
    }

  return &g_gc9d01_fb[display].vtable;
}

void up_fbuninitialize(int display)
{
  UNUSED(display);
}

/****************************************************************************
 * Name: bk7258_gc9d01_fb_fill
 *
 * Description:
 *   Bring-up helper: fills one display's framebuffer with a solid RGB565
 *   colour and pushes it.  This is the first thing that can prove the whole
 *   chain (bus framing, init sequence, CASET/RASET, pixel burst) actually
 *   reaches the glass -- the panel has no readable ID register, so until
 *   something is visible there is no evidence the init sequence worked.
 *
 ****************************************************************************/

int bk7258_gc9d01_fb_fill(int display, uint16_t rgb565)
{
  FAR struct gc9d01_fb_s *priv;
  FAR uint16_t *px;
  int i;

  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  priv = &g_gc9d01_fb[display];
  px = (FAR uint16_t *)priv->fbmem;

  if (px == NULL)
    {
      return -ENODEV;
    }

  for (i = 0; i < GC9D01_XRES * GC9D01_YRES; i++)
    {
      px[i] = rgb565;
    }

  printf("gc9d01_fb[%d]: fill 0x%04x pushed\n", display, rgb565);

  return gc9d01_push(priv);
}

/****************************************************************************
 * Name: greeting_style
 *
 * Description:
 *   The pen and layout the boot greeting is drawn with.  These are the same
 *   numbers as 'hello em=52 thick=4', so the boot animation and the shell
 *   command produce the same strokes -- they now share one renderer
 *   (hello_paint.c) and one stroke font (hello_font.c) instead of the panel
 *   driver carrying its own 5x7 bitmap copy of the word.
 *
 ****************************************************************************/

#define GC9D01_GREETING_TEXT   "hello vela"
#define GC9D01_GREETING_EM     52
#define GC9D01_GREETING_THICK  4
#define GC9D01_GREETING_STEPS  20

static int32_t greeting_style(FAR struct hs_style_s *st)
{
  int32_t budget = (GC9D01_XRES * 16 * 85) / 100;
  int32_t width = 0;
  int32_t total;

  memset(st, 0, sizeof(*st));
  st->fg      = 0xffff;
  st->bg      = 0x0000;
  st->em16    = GC9D01_GREETING_EM * 16;
  st->thick16 = GC9D01_GREETING_THICK * 16;

  /* Baseline is nudged below the centre by the same fraction the command
   * uses, so the word sits optically centred rather than mathematically.
   */

  st->baseline16 = (GC9D01_YRES * 16) / 2 + (st->em16 * 10) / 64;
  total = hs_measure(GC9D01_GREETING_TEXT, st, &width);

  /* Auto-fit, same 85% chord budget as the shell command.  The glass is
   * round, so the usable width is a chord rather than the full 160 pixels,
   * and GC9D01_GREETING_EM is the requested size rather than a promise: at
   * em 52 "hello vela" is about 180 pixels wide and would lose its first
   * letter off the left edge, which looks like a font bug rather than an
   * overflow.
   */

  if (width > budget && width > 0)
    {
      st->em16 = (st->em16 * budget) / width;
      st->thick16 = (st->thick16 * budget) / width;

      if (st->thick16 < 2 * 16)
        {
          st->thick16 = 2 * 16;
        }

      st->baseline16 = (GC9D01_YRES * 16) / 2 + (st->em16 * 10) / 64;
      total = hs_measure(GC9D01_GREETING_TEXT, st, &width);
    }

  st->cx16 = (GC9D01_XRES * 16 - width) / 2;
  return total;
}

/****************************************************************************
 * Name: bk7258_gc9d01_fb_hello
 *
 * Description:
 *   The greeting, complete, in one shot.  Kept for callers that cannot
 *   animate; the boot path uses bk7258_gc9d01_fb_hello_animate().
 *
 ****************************************************************************/

int bk7258_gc9d01_fb_hello(int display)
{
  FAR struct gc9d01_fb_s *priv;
  struct hs_style_s st;
  int32_t total;

  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  priv = &g_gc9d01_fb[display];
  if (priv->fbmem == NULL)
    {
      return -ENODEV;
    }

  total = greeting_style(&st);

  hs_clear(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES, &st);
  hs_stroke(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES,
            GC9D01_GREETING_TEXT, &st, 0, total);

  return gc9d01_push(priv);
}

/****************************************************************************
 * Name: bk7258_gc9d01_fb_hello_animate
 *
 * Description:
 *   Writes the greeting one pen stroke at a time, all selected panels
 *   advancing together, which is what the 'hello' shell command does.
 *
 *   displays is a bitmask of panels.  Only the newly written stroke is drawn
 *   each step -- the pen adds ink and never repaints -- so a step costs one
 *   short stroke plus a full-frame push per panel.  The panel takes no
 *   partial update (see gc9d01_updatearea()), so the push dominates and sets
 *   the pace; the elapsed time is reported to keep that cost visible in the
 *   boot log.
 *
 *   Reusing the command's renderer was not possible while it lived with the
 *   application: bring-up cannot start an application in this configuration
 *   (neither exec_builtin() nor posix_spawn() is built), which showed up as
 *   an undefined reference at link time.  Moving the renderer to the board is
 *   what made one implementation serve both.
 *
 ****************************************************************************/

int bk7258_gc9d01_fb_hello_animate(int displays, int steps)
{
  struct hs_style_s st;
  clock_t start = clock_systime_ticks();
  int32_t total;
  int32_t drawn = 0;
  int display;
  int step;
  int drew = 0;

  if (steps < 1)
    {
      steps = 1;
    }

  total = greeting_style(&st);
  if (total <= 0)
    {
      return -EINVAL;
    }

  for (display = 0; display < GC9D01_NDISPLAYS; display++)
    {
      if ((displays & (1 << display)) != 0 &&
          g_gc9d01_fb[display].fbmem != NULL)
        {
          hs_clear(g_gc9d01_fb[display].fbmem, GC9D01_STRIDE,
                   GC9D01_XRES, GC9D01_YRES, &st);
          (void)gc9d01_push(&g_gc9d01_fb[display]);
          drew = 1;
        }
    }

  if (drew == 0)
    {
      return -ENODEV;
    }

  for (step = 1; step <= steps; step++)
    {
      /* Same smoothstep the command uses, so the pen accelerates into the
       * stroke and settles out of it rather than moving at a constant rate.
       */

      int32_t target = (int32_t)(((int64_t)total *
                        hs_ease((step * 1000) / steps)) / 1000);
      FAR uint8_t *master = NULL;

      if (step >= steps)
        {
          target = total;
        }

      if (target <= drawn)
        {
          continue;
        }

      for (display = 0; display < GC9D01_NDISPLAYS; display++)
        {
          if ((displays & (1 << display)) == 0 ||
              g_gc9d01_fb[display].fbmem == NULL)
            {
              continue;
            }

          /* Rasterize once, then copy.  Both panels show the same word and
           * have identical geometry and stride, so stroking each of them
           * separately would pay for the same pixels twice: measured at
           * ~1.8ms per path pixel, the second pass cost about as much as a
           * full frame push.  memcpy of 51200 bytes between two kernel-RAM
           * framebuffers is far cheaper.
           */

          if (master == NULL)
            {
              hs_stroke(g_gc9d01_fb[display].fbmem, GC9D01_STRIDE,
                        GC9D01_XRES, GC9D01_YRES, GC9D01_GREETING_TEXT, &st,
                        drawn, target);
              master = g_gc9d01_fb[display].fbmem;
            }
          else
            {
              memcpy(g_gc9d01_fb[display].fbmem, master, GC9D01_FBLEN);
            }

          (void)gc9d01_push(&g_gc9d01_fb[display]);
        }

      drawn = target;
    }

  printf("gc9d01_fb: greeting written in %lu ms (%d steps, %d px path, "
         "em %d, pen %d)\n",
         (unsigned long)TICK2MSEC(clock_systime_ticks() - start), steps,
         (int)(total / 16), (int)(st.em16 / 16), (int)(st.thick16 / 16));

  return OK;
}

/****************************************************************************
 * Name: bk7258_gc9d01_fb_text / bk7258_gc9d01_fb_two_lines
 *
 * Description:
 *   Draw one word, or two lines, and push once.  These are what the
 *   event-driven status screen uses (bk7258_status_screen.c): the product
 *   spec forbids a live preview and asks for a state plus a one-or-two-line
 *   summary, refreshed only when it changes.
 *
 *   Sized to the panel rather than to the text: a 160x160 round display shows
 *   roughly six characters per line at a legible stroke width, so callers
 *   are expected to have shortened the text already.  Text the font cannot
 *   draw returns -EINVAL instead of an empty screen.
 *
 ****************************************************************************/

static int gc9d01_fb_lines(int display, FAR const char *const *lines,
                           int nlines, uint16_t fg)
{
  FAR struct gc9d01_fb_s *priv;
  struct hs_style_s st;
  int i;

  if (display < 0 || display >= GC9D01_NDISPLAYS || nlines < 1)
    {
      return -EINVAL;
    }

  priv = &g_gc9d01_fb[display];
  if (priv->fbmem == NULL)
    {
      return -ENODEV;
    }

  memset(&st, 0, sizeof(st));
  st.fg = fg;
  st.bg = 0x0000u;
  st.em16 = (nlines > 1 ? 26 : 44) * 16;
  st.thick16 = (nlines > 1 ? 2 : 3) * 16;
  st.cx16 = (GC9D01_XRES / 2) * 16;

  hs_clear(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES, &st);

  for (i = 0; i < nlines; i++)
    {
      int32_t total;

      if (lines[i] == NULL || lines[i][0] == '\0')
        {
          continue;   /* An empty line just leaves the cleared background. */
        }

      /* Baselines: one line centred, two lines split around the centre. */

      st.baseline16 = nlines > 1 ?
                      ((GC9D01_YRES / 2) + (i == 0 ? -6 : 30)) * 16 :
                      ((GC9D01_YRES / 2) + 16) * 16;

      total = hs_measure(lines[i], &st, NULL);
      if (total <= 0)
        {
          return -EINVAL;
        }

      hs_stroke(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES,
                lines[i], &st, 0, total);
    }

  return gc9d01_push(priv);
}

int bk7258_gc9d01_fb_text(int display, FAR const char *text, uint16_t colour)
{
  FAR const char *lines[1];

  lines[0] = text;
  return gc9d01_fb_lines(display, lines, 1, colour);
}

int bk7258_gc9d01_fb_two_lines(int display, FAR const char *line1,
                               FAR const char *line2)
{
  FAR const char *lines[2];

  lines[0] = line1;
  lines[1] = line2;
  return gc9d01_fb_lines(display, lines, 2, 0xffffu);
}

/****************************************************************************
 * Name: bk7258_gc9d01_fb_test_pattern
 *
 * Description:
 *   Draws four quadrants (red / green / blue / white) with a black border.
 *   Colour order and geometry are both wrong-detectable by eye: a swapped
 *   byte order turns red into something else, and a stride mistake shears
 *   the quadrant boundaries.
 *
 ****************************************************************************/

int bk7258_gc9d01_fb_test_pattern(int display)
{
  FAR struct gc9d01_fb_s *priv;
  FAR uint16_t *px;
  int x;
  int y;

  if (display < 0 || display >= GC9D01_NDISPLAYS)
    {
      return -EINVAL;
    }

  priv = &g_gc9d01_fb[display];
  px = (FAR uint16_t *)priv->fbmem;

  if (px == NULL)
    {
      return -ENODEV;
    }

  for (y = 0; y < GC9D01_YRES; y++)
    {
      for (x = 0; x < GC9D01_XRES; x++)
        {
          uint16_t c;

          if (x < 4 || y < 4 || x >= GC9D01_XRES - 4 ||
              y >= GC9D01_YRES - 4)
            {
              c = 0x0000;                                  /* black edge */
            }
          else if (y < GC9D01_YRES / 2)
            {
              c = (x < GC9D01_XRES / 2) ? 0xf800 : 0x07e0;  /* red green */
            }
          else
            {
              c = (x < GC9D01_XRES / 2) ? 0x001f : 0xffff;  /* blue white */
            }

          px[y * GC9D01_XRES + x] = c;
        }
    }

  printf("gc9d01_fb[%d]: test pattern drawn (TL red, TR green, BL blue, "
         "BR white, 4px black border)\n", display);

  return gc9d01_push(priv);
}

