/****************************************************************************
 * Public Functions
 ****************************************************************************/

void bk7258_lcd_spi_init(int bus, unsigned int dc_pin)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);

  if (b == NULL)
    {
      return;
    }

  b->dc_pin = dc_pin;

  /* 1. Module clock gate.  Without this the controller's command state
   * machine has no clock and cmd_start_done never asserts.
   */

  modifyreg32(BK7258_SYS_DEVCLK_EN, 0, b->clk_gate);

  /* 2. Source clock: 480MHz / 8 = 60MHz, the divider path bk_qspi_init()
   * uses.  config.clk_rate stays 0 (cleared in step 4).  Note the two
   * controllers use different sysctrl registers.
   */

  modifyreg32(b->clkdiv_reg, b->ckdiv_mask,
              (QSPI_SRC_CLK_DIV_60M << b->ckdiv_shift) | b->cksel_480m);

  /* 3. Pinmux CLK/CSN/IO0 only.  The D/C pad must stay a plain GPIO --
   * handing it to the controller is what left the panel unable to tell
   * commands from data.  Idle high = "data", matching
   * lcd_spi_device_gpio_init()'s initial state.
   */

  bk7258_gpio_set_function(b->clk_pin, b->pinmux);
  bk7258_gpio_set_function(b->csn_pin, b->pinmux);
  bk7258_gpio_set_function(b->io0_pin, b->pinmux);
  bk7258_gpio_output(b->dc_pin, true);

  /* 4. Controller enable, qspi_ll_init_common(): qspi_en + io2_io3_mode.
   * io2_io3_mode makes IO2/IO3 driven from config.io2/io3 instead of by
   * the shifter, which is correct when only one data line is wired.
   */

  modifyreg32(b->base + QSPI_OFF_CONFIG, QSPI_CONFIG_CLK_RATE_MASK,
              QSPI_CONFIG_QSPI_EN | QSPI_CONFIG_IO2_IO3_MODE);

  /* 5. Soft-reset pulse.  Order and final state copied from
   * lcd_spi_driver_init_with_qspi(): disable (0), delay, enable (1).
   */

  modifyreg32(b->base + QSPI_OFF_GLB_CTRL, QSPI_GLB_CTRL_SOFT_RESET, 0);
  up_udelay(10);
  modifyreg32(b->base + QSPI_OFF_GLB_CTRL, 0, QSPI_GLB_CTRL_SOFT_RESET);

  /* 6. Data-window transfer shape for the pixel path. */

  putreg32(QSPI_CMD_A_CFG2_MAPPING_MODE, b->base + QSPI_OFF_CMD_A_CFG2);

  b->initialized = true;

  printf("bk7258_lcd_spi[%s]: init: devclk_en=0x%08x clkdiv=0x%08x "
         "config=0x%08x glb_ctrl=0x%08x cmd_a_cfg2=0x%08x "
         "pins=CLK%u/CS%u/SDA%u dc=GPIO%u\n", b->name,
         (unsigned int)getreg32(BK7258_SYS_DEVCLK_EN),
         (unsigned int)getreg32(b->clkdiv_reg),
         (unsigned int)getreg32(b->base + QSPI_OFF_CONFIG),
         (unsigned int)getreg32(b->base + QSPI_OFF_GLB_CTRL),
         (unsigned int)getreg32(b->base + QSPI_OFF_CMD_A_CFG2),
         (unsigned int)b->clk_pin, (unsigned int)b->csn_pin,
         (unsigned int)b->io0_pin, (unsigned int)b->dc_pin);
}

bool bk7258_lcd_spi_ready(int bus)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);

  return b != NULL && b->initialized;
}

bool bk7258_lcd_spi_write_cmd(int bus, uint8_t cmd)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);

  if (b == NULL || !b->initialized)
    {
      return false;
    }

  bk7258_gpio_write(b->dc_pin, false);

  return lcd_xfer(b, &cmd, 1u);
}

bool bk7258_lcd_spi_write_data(int bus, const uint8_t *data, uint32_t len)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);

  if (b == NULL || !b->initialized || data == NULL || len == 0)
    {
      return false;
    }

  bk7258_gpio_write(b->dc_pin, true);

  return lcd_xfer(b, data, len);
}

bool bk7258_lcd_spi_write_cmd_data(int bus, uint8_t cmd,
                                   const uint8_t *data, uint32_t len)
{
  if (!bk7258_lcd_spi_write_cmd(bus, cmd))
    {
      return false;
    }

  if (len == 0)
    {
      return true;
    }

  return bk7258_lcd_spi_write_data(bus, data, len);
}

bool bk7258_lcd_spi_write_frame(int bus, const void *frame, size_t len)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);
  const uint32_t *src = frame;
  size_t words = len / 4u;
  size_t i;

  if (b == NULL || !b->initialized || frame == NULL || len == 0 ||
      (len & 3u) != 0)
    {
      return false;
    }

  /* RAMWR goes out as an ordinary DC-low command; CS is allowed to
   * deassert afterwards, exactly as bk_lcd_spi_frame_display() does.
   */

  if (!bk7258_lcd_spi_write_cmd(bus, GC9D01_CMD_RAMWR))
    {
      return false;
    }

  bk7258_gpio_write(b->dc_pin, true);

  /* lcd_spi_quad_write_start(): park the command channel, hold CS low for
   * the whole burst, hand the data line to the memory-mapped window and
   * stop the command path from generating SCK.
   */

  putreg32(0, b->base + QSPI_OFF_CMD_C_L);
  putreg32(0, b->base + QSPI_OFF_CMD_C_H);
  putreg32(0, b->base + QSPI_OFF_CMD_C_CFG1);
  putreg32(0, b->base + QSPI_OFF_CMD_C_CFG2);

  modifyreg32(b->base + QSPI_OFF_CONFIG, 0, QSPI_CONFIG_FORCE_SPI_CS_LOW);
  modifyreg32(b->base + QSPI_OFF_CONFIG, 0, QSPI_CONFIG_IO_CPU_MEM_SEL);
  modifyreg32(b->base + QSPI_OFF_CONFIG, 0, QSPI_CONFIG_DISABLE_CMD_SCK);

  if (b->frames < 2)
    {
      printf("bk7258_lcd_spi[%s]: frame %u: config=0x%08x words=%u "
             "src=%p first_px=0x%04x swap=%u\n", b->name,
             (unsigned int)b->frames,
             (unsigned int)getreg32(b->base + QSPI_OFF_CONFIG),
             (unsigned int)words, frame,
             (unsigned int)(src[0] & 0xffff),
             (unsigned int)g_swap_bytes);
    }

  /* CPU-driven copy.  The controller back-pressures the AHB write when its
   * FIFO is full, so this self-throttles to the wire rate; 160x160 RGB565
   * measured ~27ms on the bus.
   *
   * The destination address increments: lcd_spi_dma_single_mode_config()
   * sets dst.start_addr = qspi_data, dst.end_addr = qspi_data + data_len
   * and dst.addr_inc_en = DMA_ADDR_INC_ENABLE, so the window is a range,
   * not a single FIFO register.
   */

  if (g_swap_bytes)
    {
      for (i = 0; i < words; i++)
        {
          putreg32(gc9_swap16x2(src[i]), b->window + i * 4u);
        }
    }
  else
    {
      for (i = 0; i < words; i++)
        {
          putreg32(src[i], b->window + i * 4u);
        }
    }

  up_udelay(QSPI_FRAME_TAIL_DELAY_US);

  /* lcd_spi_quad_write_stop(), same order as the reference. */

  modifyreg32(b->base + QSPI_OFF_CONFIG, QSPI_CONFIG_DISABLE_CMD_SCK, 0);
  modifyreg32(b->base + QSPI_OFF_CONFIG, QSPI_CONFIG_FORCE_SPI_CS_LOW, 0);
  modifyreg32(b->base + QSPI_OFF_CONFIG, QSPI_CONFIG_IO_CPU_MEM_SEL, 0);

  b->frames++;
  return true;
}

uint32_t bk7258_lcd_spi_frame_count(int bus)
{
  FAR struct lcd_bus_s *b = lcd_bus(bus);

  return b != NULL ? b->frames : 0;

/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_status_screen.c
 *
 * Event-driven status and summary screen.
 *
 * Why this exists instead of the live preview
 * ------------------------------------------
 * The product spec is explicit: the panels must not run a real-time camera
 * preview, and they must refresh only when a key, a state or a result
 * changes -- "屏幕仅事件触发刷新，不运行实时 Camera Preview", with the
 * display carrying "状态" and "一至两行摘要".  A 160x160 round panel cannot
 * usefully show a 640x480 scene anyway, and a 30fps preview costs 24-26ms of
 * QSPI per panel per frame, which is exactly the budget the spec wants left
 * for audio.
 *
 * camera_preview stays in the tree as a *diagnostic*: it is how a byte-order
 * or geometry fault is made visible (docs/reference/display.md).  It is no
 * longer what the product path draws.
 *
 * What it draws
 * -------------
 *   left panel  (fb0): the state -- one word plus a state colour, so the
 *                      state is readable across the room.
 *   right panel (fb1): up to two lines of summary text.
 *
 * Text uses the stroke font this board already has (hello_font.c).  That font
 * covers ASCII only, so Chinese summaries -- which is what the cloud actually
 * returns -- cannot be drawn yet; bk7258_status_screen_summary() reports that
 * by returning -ENOSYS for non-ASCII input rather than drawing a row of
 * blanks and pretending.  Wiring in a CJK glyph source is tracked separately.
 *
 * Refresh is one full-frame push per panel, only when something changed: the
 * panel takes no partial update (see gc9d01_updatearea()), and repainting an
 * unchanged screen would spend 25ms for nothing.  Nothing here holds a camera,
 * audio or network lock, and a failed push is reported but never propagated --
 * the spec requires display failure not to break the data path.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <arch/board/hello_paint.h>

#include "bk7258_gc9d01_fb.h"
#include "bk7258_status_screen.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define STATUS_PANEL   0        /* fb0 shows the state */
#define SUMMARY_PANEL  1        /* fb1 shows the summary */

#define SUMMARY_LINES  2
#define SUMMARY_CHARS  24

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* What is on the glass right now, so an unchanged update costs nothing. */

static enum bk7258_status_e g_shown_state = BK7258_STATUS_MAX;
static char g_shown_summary[SUMMARY_LINES][SUMMARY_CHARS + 1];

/* State names and colours.  The words are the spec's own state names for the
 * two modes, kept short enough to read on a 160px round panel.
 */

static const struct
{
  FAR const char *text;
  uint16_t colour;              /* RGB565 */
}
g_states[BK7258_STATUS_MAX] =
{
  [BK7258_STATUS_IDLE]         = { "idle",    0x4208u },  /* grey  */
  [BK7258_STATUS_CONSENT]      = { "ready?",  0xfd20u },  /* amber */
  [BK7258_STATUS_RECORDING]    = { "rec",     0xf800u },  /* red   */
  [BK7258_STATUS_FINALIZING]   = { "wait",    0xfd20u },
  [BK7258_STATUS_RESULT_READY] = { "done",    0x07e0u },  /* green */
  [BK7258_STATUS_LISTENING]    = { "listen",  0x001fu },  /* blue  */
  [BK7258_STATUS_TRANSCRIBING] = { "...",     0x001fu },
  [BK7258_STATUS_THINKING]     = { "think",   0x001fu },
  [BK7258_STATUS_SPEAKING]     = { "speak",   0x07e0u },
  [BK7258_STATUS_CANCELLED]    = { "cancel",  0x4208u },
  [BK7258_STATUS_ERROR]        = { "error",   0xf800u },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static bool status_is_ascii(FAR const char *text)
{
  while (*text != '\0')
    {
      if ((unsigned char)*text > 0x7fu)
        {
          return false;
        }

      text++;
    }

  return true;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_status_screen_state(enum bk7258_status_e state)
{
  int ret;

  if ((unsigned int)state >= BK7258_STATUS_MAX)
    {
      return -EINVAL;
    }

  if (state == g_shown_state)
    {
      return OK;                /* Already on the glass */
    }

  ret = bk7258_gc9d01_fb_text(STATUS_PANEL, g_states[state].text,
                              g_states[state].colour);
  if (ret < 0)
    {
      /* Display trouble must not stop the caller: the spec puts the data path
       * ahead of the screen.
       */

      printf("status_screen: state %s not drawn: %d\n",
             g_states[state].text, ret);
      return ret;
    }

  g_shown_state = state;

  /* Entering idle also clears the summary panel.
   *
   * Without this the two panels disagree after boot: the greeting is drawn on
   * both, then only the state panel is repainted, so one round display says
   * "idle" while the other still says "hello vela" -- which reads as a broken
   * panel, and was reported as one.  It matters beyond boot too: a summary
   * from a finished session must not sit next to an idle state, or the screen
   * claims something the device is no longer doing.
   */

  if (state == BK7258_STATUS_IDLE)
    {
      int cleared = bk7258_gc9d01_fb_two_lines(SUMMARY_PANEL, "", "");

      if (cleared < 0)
        {
          printf("status_screen: summary panel not cleared: %d\n", cleared);
        }
      else
        {
          g_shown_summary[0][0] = '\0';
          g_shown_summary[1][0] = '\0';
        }
    }

  /* One line per actual repaint.  Kept because it is the only outside
   * evidence that the panel was painted -- there is no way to read the glass
   * back -- and because it makes the "only on change" rule checkable: a
   * screen that repaints on a timer would show up here as a stream.
   */

  printf("status_screen: state %s drawn\n", g_states[state].text);
  return OK;
}

int bk7258_status_screen_summary(FAR const char *line1, FAR const char *line2)
{
  char l1[SUMMARY_CHARS + 1];
  char l2[SUMMARY_CHARS + 1];
  int ret;

  strlcpy(l1, line1 != NULL ? line1 : "", sizeof(l1));
  strlcpy(l2, line2 != NULL ? line2 : "", sizeof(l2));

  if (!status_is_ascii(l1) || !status_is_ascii(l2))
    {
      /* The stroke font is ASCII-only.  Say so instead of drawing blanks:
       * a caller that gets -ENOSYS can fall back to TTS, which is the spec's
       * primary output channel anyway.
       */

      return -ENOSYS;
    }

  if (strcmp(l1, g_shown_summary[0]) == 0 &&
      strcmp(l2, g_shown_summary[1]) == 0)
    {
      return OK;
    }

  ret = bk7258_gc9d01_fb_two_lines(SUMMARY_PANEL, l1, l2);
  if (ret < 0)
    {
      printf("status_screen: summary not drawn: %d\n", ret);
      return ret;
    }

  strlcpy(g_shown_summary[0], l1, sizeof(g_shown_summary[0]));
  strlcpy(g_shown_summary[1], l2, sizeof(g_shown_summary[1]));
  return OK;
}

void bk7258_status_screen_invalidate(void)
{
  g_shown_state = BK7258_STATUS_MAX;
  g_shown_summary[0][0] = '\0';
  g_shown_summary[1][0] = '\0';
}
/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_status_screen.h
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_STATUS_SCREEN_H
#define __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_STATUS_SCREEN_H

#include <nuttx/config.h>
#include <nuttx/compiler.h>

/* The states the two modes go through, spelled as the product spec spells
 * them (social: IDLE/CONSENT/RECORDING/FINALIZING/RESULT_READY, voice:
 * LISTENING/TRANSCRIBING/THINKING/SPEAKING, plus CANCELLED and ERROR).
 */

enum bk7258_status_e
{
  BK7258_STATUS_IDLE = 0,
  BK7258_STATUS_CONSENT,
  BK7258_STATUS_RECORDING,
  BK7258_STATUS_FINALIZING,
  BK7258_STATUS_RESULT_READY,
  BK7258_STATUS_LISTENING,
  BK7258_STATUS_TRANSCRIBING,
  BK7258_STATUS_THINKING,
  BK7258_STATUS_SPEAKING,
  BK7258_STATUS_CANCELLED,
  BK7258_STATUS_ERROR,
  BK7258_STATUS_MAX
};

/* Both are no-ops when what they would draw is already on the glass, so a
 * caller may call them on every event without costing a 25ms push.
 */

int bk7258_status_screen_state(enum bk7258_status_e state);
int bk7258_status_screen_summary(FAR const char *line1,
                                 FAR const char *line2);
void bk7258_status_screen_invalidate(void);

#endif /* __BOARDS_BEKEN_BK7258_AP_SRC_BK7258_STATUS_SCREEN_H */

/****************************************************************************
 * apps/hello_screen/hello_paint.h
 *
 * Pen-stroke renderer for the greeting animation.
 *
 * The interface is arc-length based on purpose: the animation advances a pen
 * along the text's path, so a frame is "draw the path between these two
 * distances" rather than "draw the whole thing at progress p".  That lets the
 * animation add only the newly written stroke each frame instead of clearing
 * and redrawing, which on this board is the difference between a smooth
 * animation and a slideshow -- the panels take ~60ms each to push, and
 * redrawing the whole word every frame would add to that for no visible gain.
 *
 * No dependency on camera_preview's renderer: this module writes RGB565 into
 * caller memory and nothing else, so it can be tested on the host.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __APPS_HELLO_SCREEN_HELLO_PAINT_H
#define __APPS_HELLO_SCREEN_HELLO_PAINT_H

#include <stddef.h>
#include <stdint.h>

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct hs_style_s
{
  uint16_t fg;        /* pen colour, RGB565                               */
  uint16_t bg;        /* background, RGB565                               */
  int32_t  em16;      /* em size in 1/16 pixel (the 64-unit glyph box)    */
  int32_t  thick16;   /* pen width in 1/16 pixel                          */
  int32_t  cx16;      /* text centre x in 1/16 pixel                      */
  int32_t  baseline16;/* baseline y in 1/16 pixel                         */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Total pen travel for text, in 1/16 pixel, and its ink width through
 * width16 when that is not NULL.  Returns 0 for text the font cannot draw.
 */

int32_t hs_measure(const char *text, const struct hs_style_s *st,
                   int32_t *width16);

/* Smoothstep on 0..1000, used to pace the reveal.  Exposed so the boot
 * animation in the panel driver and the shell command move the pen the same
 * way: a constant speed looks mechanical and a quadratic ease-out starts too
 * abruptly.
 */

int32_t hs_ease(int32_t permille);

/* Fill the whole canvas with st->bg. */

void hs_clear(uint8_t *buf, size_t stride, int w, int h,
              const struct hs_style_s *st);

/* Draw the part of text's pen path between arc lengths from16 and to16.
 * Passing 0 and hs_measure()'s result draws the complete word.
 */

void hs_stroke(uint8_t *buf, size_t stride, int w, int h,
               const char *text, const struct hs_style_s *st,
               int32_t from16, int32_t to16);

#endif /* __APPS_HELLO_SCREEN_HELLO_PAINT_H */
/****************************************************************************
 * apps/hello_screen/hello_font.h
 *
 * Monoline stroke font for the boot greeting.
 *
 * Glyphs are paths, not bitmaps, because the animation reveals the text the
 * way a pen would draw it: the renderer needs to know where the stroke goes
 * and how long it is, which a bitmap cannot tell it.
 *
 * Coordinates are in a per-glyph box: x from 0 to advance, y from 0 (top of
 * the ascender) to 64.  The baseline is y=48 and the x-height top is y=28,
 * so a lowercase bowl is 20 units tall.  int8_t is enough for every value
 * and keeps the table small.
 *
 * Angles are in 1/64 of a turn with y pointing down: 0 is +x (right), 16 is
 * down, 32 is left, 48 is up.  Arcs are drawn from a0 towards a1, so a1 < a0
 * means counter-clockwise on screen.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __APPS_HELLO_SCREEN_HELLO_FONT_H
#define __APPS_HELLO_SCREEN_HELLO_FONT_H

#include <stdint.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define HS_EM          64      /* glyph box height, in font units          */
#define HS_BASELINE    48
#define HS_XHEIGHT_TOP 28

enum hs_op_e
{
  HS_END = 0,
  HS_MOVE,               /* a=x  b=y                                       */
  HS_LINE,               /* a=x  b=y                                       */
  HS_ARC                 /* a=cx b=cy c=r  d=a0 e=a1  (1/64 turns)         */
};

struct hs_op_s
{
  int8_t op;
  int8_t a;
  int8_t b;
  int8_t c;
  int8_t d;
  int8_t e;
};

struct hs_glyph_s
{
  char                    ch;
  int8_t                  advance;
  const struct hs_op_s   *ops;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Glyph for ch, or NULL when the font has no such character. */

const struct hs_glyph_s *hs_font_lookup(char ch);

#endif /* __APPS_HELLO_SCREEN_HELLO_FONT_H */
